/** @file Quy tắc vẽ DynaGeo — spec JSON + renderer canvas */

export const DRAW_SPEC_VERSION = 1

export const DEFAULT_CANVAS = {
  width: 800,
  height: 560,
  padding: 36,
  background: '#f8fafc',
}

function paramMap(params, overrides = {}) {
  const m = { ...overrides }
  for (const p of params || []) {
    if (p?.id != null && m[p.id] === undefined) m[p.id] = Number(p.value)
  }
  return m
}

/** params + variables + rules có expr → giá trị dùng khi vẽ */
export function buildParamMap(spec, overrides = {}) {
  const pmap = paramMap(spec?.params, overrides)
  for (const v of spec?.variables || []) {
    if (!v?.id) continue
    if (overrides[v.id] !== undefined) {
      pmap[v.id] = overrides[v.id]
      continue
    }
    if (v.expr) pmap[v.id] = resolveNumber(v.expr, pmap)
    else if (v.value != null) pmap[v.id] = Number(v.value)
  }
  for (const r of spec?.rules || []) {
    if (r?.target && r.expr) pmap[r.target] = resolveNumber(r.expr, pmap)
  }
  return pmap
}

export const VIEW_PRESETS = {
  front: { yaw: 0, pitch: 0, zoom: 1, panX: 0, panY: 0 },
  top: { yaw: 0, pitch: -1.35, zoom: 1, panX: 0, panY: 0 },
  right: { yaw: 1.57, pitch: 0, zoom: 1, panX: 0, panY: 0 },
  left: { yaw: -1.57, pitch: 0, zoom: 1, panX: 0, panY: 0 },
  back: { yaw: 3.14, pitch: 0, zoom: 1, panX: 0, panY: 0 },
  iso: { yaw: 0.75, pitch: 0.55, zoom: 1, panX: 0, panY: 0 },
  bottom: { yaw: 0, pitch: 1.35, zoom: 1, panX: 0, panY: 0 },
}

/** Thay {{id}}, tên tham số, và cho phép Math.sin/cos/sqrt/PI */
function resolveNumber(value, pmap) {
  if (typeof value === 'number' && Number.isFinite(value)) return value
  if (value == null) return 0
  let tpl = String(value).trim()
  tpl = tpl.replace(/\{\{(\w+)\}\}/g, (_, id) => String(pmap[id] ?? 0))
  tpl = tpl.replace(/\^/g, '**')
  const ids = Object.keys(pmap).sort((a, b) => b.length - a.length)
  for (const id of ids) {
    tpl = tpl.replace(new RegExp(`\\b${id}\\b`, 'g'), String(pmap[id]))
  }
  if (!tpl) return 0
  try {
    if (!/^[0-9+\-*/().\s\w]+$/.test(tpl)) return Number(tpl) || 0
    // eslint-disable-next-line no-new-func
    return Function('Math', `"use strict"; return (${tpl});`)(Math)
  } catch {
    return Number(tpl) || 0
  }
}

const ISO_COS = Math.cos(Math.PI / 6)
const ISO_SIN = Math.sin(Math.PI / 6)

function project3d(x, y, z, ox, oy, scale) {
  return {
    x: (x - z) * ISO_COS * scale + ox,
    y: -(y + (x + z) * ISO_SIN) * scale + oy,
  }
}

export const DEFAULT_VIEW = {
  yaw: 0,
  pitch: 0,
  zoom: 1,
  panX: 0,
  panY: 0,
}

export function normalizeView(view = {}) {
  const pitch = Number(view.pitch ?? 0)
  const lim = Math.PI / 2 - 0.12
  return {
    yaw: Number(view.yaw ?? 0),
    pitch: Math.max(-lim, Math.min(lim, pitch)),
    zoom: Math.max(0.2, Math.min(5, Number(view.zoom ?? 1))),
    panX: Number(view.panX ?? 0),
    panY: Number(view.panY ?? 0),
  }
}

function rotateY3(x, y, z, ang) {
  const c = Math.cos(ang)
  const s = Math.sin(ang)
  return { x: x * c + z * s, y, z: -x * s + z * c }
}

function rotateX3(x, y, z, ang) {
  const c = Math.cos(ang)
  const s = Math.sin(ang)
  return { x, y: y * c - z * s, z: y * s + z * c }
}

function orbitModelPoint(x, y, z, center, view, layout) {
  const v = normalizeView(view)
  let px = (x - center.mx) * v.zoom
  let py = (y - center.my) * v.zoom
  let pz = (z - center.mz) * v.zoom
  let r = rotateY3(px, py, pz, v.yaw)
  r = rotateX3(r.x, r.y, r.z, v.pitch)
  const scale = layout.scale3d
  const ox = Number.isFinite(layout.ox) ? layout.ox : 0
  const oy = Number.isFinite(layout.oy) ? layout.oy : 0
  if (layout.orbitIso) {
    return {
      x: (r.x - r.z) * ISO_COS * scale + ox + v.panX,
      y: -(r.y + (r.x + r.z) * ISO_SIN) * scale + oy + v.panY,
    }
  }
  return { x: ox + r.x + v.panX, y: oy + r.y + v.panY }
}

function orbitCenterFromModel(model2d, points3d) {
  const keys3d = Object.keys(points3d || {})
  if (keys3d.length) {
    let mx = 0
    let my = 0
    let mz = 0
    for (const id of keys3d) {
      const p = points3d[id]
      mx += p.x
      my += p.y
      mz += p.z || 0
    }
    const n = keys3d.length
    return { mx: mx / n, my: my / n, mz: mz / n }
  }
  const vals = Object.values(model2d || {})
  if (!vals.length) return { mx: 0, my: 0, mz: 0 }
  const mx = vals.reduce((s, p) => s + p.x, 0) / vals.length
  const my = vals.reduce((s, p) => s + p.y, 0) / vals.length
  return { mx, my, mz: 0 }
}

function applyViewToPoints(points2d, model2d, points3d, layout, view, planarMode = '2d') {
  const v = normalizeView(view)
  if (!v.yaw && !v.pitch && v.zoom === 1 && !v.panX && !v.panY) return
  const center = orbitCenterFromModel(model2d, points3d)
  const useOrbit = planarMode === '3d' || Object.keys(points3d || {}).length > 0

  for (const id of Object.keys(model2d)) {
    const label = model2d[id].label
    if (!useOrbit) {
      const p = model2d[id]
      points2d[id] = {
        x: center.mx + (p.x - center.mx) * v.zoom + v.panX,
        y: center.my + (p.y - center.my) * v.zoom + v.panY,
        label,
      }
      continue
    }
    if (points3d[id]) {
      const p = points3d[id]
      const hit = orbitModelPoint(p.x, p.y, p.z, center, view, layout)
      points2d[id] = { x: hit.x, y: hit.y, label }
    } else {
      const p = model2d[id]
      const hit = orbitModelPoint(p.x, p.y, 0, center, view, layout)
      points2d[id] = { x: hit.x, y: hit.y, label }
    }
  }
}

function mapFit2dPoint(x, y, fit) {
  if (!fit?.applied) return { x, y }
  return {
    x: fit.ox + (x - fit.cx) * fit.scale,
    y: fit.oy + (y - fit.cy) * fit.scale,
  }
}

function expandBoundsWithCircles(minX, maxX, minY, maxY, commands, points2d, pmap) {
  let x0 = minX
  let x1 = maxX
  let y0 = minY
  let y1 = maxY
  for (const cmd of commands || []) {
    if (!cmd || String(cmd.op).toLowerCase() !== 'circle') continue
    let cx
    let cy
    if (cmd.center && points2d[cmd.center]) {
      cx = points2d[cmd.center].x
      cy = points2d[cmd.center].y
    } else if (cmd.cx != null && cmd.cy != null) {
      cx = resolveNumber(cmd.cx, pmap)
      cy = resolveNumber(cmd.cy, pmap)
    } else continue
    let r = resolveNumber(cmd.r ?? cmd.radius, pmap)
    if (cmd.through && points2d[cmd.through]) {
      const p = points2d[cmd.through]
      r = Math.hypot(p.x - cx, p.y - cy)
    }
    if (!(r > 0)) continue
    x0 = Math.min(x0, cx - r)
    x1 = Math.max(x1, cx + r)
    y0 = Math.min(y0, cy - r)
    y1 = Math.max(y1, cy + r)
  }
  return { minX: x0, maxX: x1, minY: y0, maxY: y1 }
}

/** Căn hình 2D vào giữa canvas; trả metadata để map nhãn/tọa độ tuyệt đối. */
function fit2dModelToCanvas(model2d, points2d, cw, ch, pad, commands, pmap) {
  const vals = Object.values(model2d || {})
  if (vals.length < 1) return null
  let minX = Infinity
  let maxX = -Infinity
  let minY = Infinity
  let maxY = -Infinity
  for (const p of vals) {
    if (!Number.isFinite(p.x) || !Number.isFinite(p.y)) continue
    minX = Math.min(minX, p.x)
    maxX = Math.max(maxX, p.x)
    minY = Math.min(minY, p.y)
    maxY = Math.max(maxY, p.y)
  }
  if (!Number.isFinite(minX)) return null
  ;({ minX, maxX, minY, maxY } = expandBoundsWithCircles(
    minX,
    maxX,
    minY,
    maxY,
    commands,
    points2d,
    pmap,
  ))
  const bw = Math.max(maxX - minX, 48)
  const bh = Math.max(maxY - minY, 48)
  const innerW = Math.max(cw - 2 * pad, 80)
  const innerH = Math.max(ch - 2 * pad, 80)
  const scale = 0.88 * Math.min(innerW / bw, innerH / bh)
  const cx = (minX + maxX) / 2
  const cy = (minY + maxY) / 2
  const ox = cw / 2
  const oy = ch / 2
  const mapPt = (p) => ({
    x: ox + (p.x - cx) * scale,
    y: oy + (p.y - cy) * scale,
    label: p.label,
  })
  for (const id of Object.keys(model2d)) {
    const next = mapPt(model2d[id])
    model2d[id] = { ...model2d[id], x: next.x, y: next.y }
    if (points2d[id]) points2d[id] = { ...points2d[id], x: next.x, y: next.y, label: next.label }
  }
  return { applied: true, scale, cx, cy, ox, oy }
}

/** Căn khối 3D vào giữa canvas (ox, oy, scale3d) theo góc xoay hiện tại. */
function center3dLayout(points3d, points2d, layout, cw, ch, pad = 36, view = null) {
  const vals = Object.values(points3d || {})
  if (!vals.length) return
  const ox0 = cw / 2
  const oy0 = ch / 2
  let scale = layout.scale3d
  const orbitCenter = orbitCenterFromModel({}, points3d)
  const useOrbit = Boolean(layout.orbitIso && view)
  const v = useOrbit ? normalizeView(view) : null

  const projectPoint = (p, ox, oy, sc) => {
    if (useOrbit) {
      return orbitModelPoint(p.x, p.y, p.z, orbitCenter, v, { ...layout, ox, oy, scale3d: sc })
    }
    return project3d(p.x, p.y, p.z, ox, oy, sc)
  }

  let minX = Infinity
  let maxX = -Infinity
  let minY = Infinity
  let maxY = -Infinity
  const projectAll = (ox, oy, sc) => {
    minX = Infinity
    maxX = -Infinity
    minY = Infinity
    maxY = -Infinity
    for (const p of vals) {
      const s = projectPoint(p, ox, oy, sc)
      minX = Math.min(minX, s.x)
      maxX = Math.max(maxX, s.x)
      minY = Math.min(minY, s.y)
      maxY = Math.max(maxY, s.y)
    }
  }
  projectAll(ox0, oy0, scale)
  const bw = Math.max(maxX - minX, 40)
  const bh = Math.max(maxY - minY, 40)
  const innerW = Math.max(cw - 2 * pad, 120)
  const innerH = Math.max(ch - 2 * pad, 120)
  const fit = 0.88 * Math.min(innerW / bw, innerH / bh)
  if (Number.isFinite(fit) && fit > 0) scale *= fit
  layout.scale3d = scale
  projectAll(ox0, oy0, scale)
  const cx = (minX + maxX) / 2
  const cy = (minY + maxY) / 2
  layout.ox = ox0 + (cw / 2 - cx)
  layout.oy = oy0 + (ch / 2 - cy)
  for (const [id, p] of Object.entries(points3d)) {
    const hit = projectPoint(p, layout.ox, layout.oy, layout.scale3d)
    if (points2d[id]) points2d[id] = { ...points2d[id], x: hit.x, y: hit.y }
  }
}

const PLANE_THEMES = {
  xy: { stroke: '#38bdf8', fill: 'rgba(56, 189, 248, 0.1)', color: '#0284c7' },
  xz: { stroke: '#60a5fa', fill: 'rgba(96, 165, 250, 0.08)', color: '#1d4ed8' },
  yz: { stroke: '#f472b6', fill: 'rgba(244, 114, 182, 0.08)', color: '#db2777' },
}

/** Bán kính lưới mặc phẳng: XY rộng (×5 so base), XZ/YZ gọn (÷4 so base). */
const PLANE_BASE_HALF = 3.5
const PLANE_DEFAULT_HALF = {
  xy: PLANE_BASE_HALF * 5,
  xz: PLANE_BASE_HALF / 4,
  yz: PLANE_BASE_HALF / 4,
}
const PLANE_XY_FIT_FACTOR = 5
/** Độ mờ lưới / nền mặt phẳng 3D */
const PLANE_GRID_ALPHA = 0.2
const PLANE_FILL_ALPHA = 0.1
const PLANE_LABEL_ALPHA = 0.55

const PLAIN_PLANE_STROKES = new Set(['#e2e8f0', '#cbd5e1', '#94a3b8'])

function planeStyleField(cmd, field, theme, use3dTheme, fallback) {
  const v = cmd[field]
  if (!use3dTheme) return v || fallback
  if (!v) return theme[field] || fallback
  if (field === 'stroke' && PLAIN_PLANE_STROKES.has(String(v).toLowerCase())) return theme.stroke
  if (field === 'fill' && String(v).includes('148,163,184')) return theme.fill
  if (field === 'color' && PLAIN_PLANE_STROKES.has(String(v).toLowerCase())) return theme.color
  return v
}

/** Bán kính lưới mặt phẳng 3D (gốc 0,0,0) — phủ khối hình + ~35% biên. */
function suggestedPlaneHalf(points3d, margin = 1.35) {
  const vals = Object.values(points3d || {})
  if (!vals.length) return 4
  let reach = 0
  for (const p of vals) {
    reach = Math.max(reach, Math.abs(p.x), Math.abs(p.y), Math.abs(p.z))
  }
  return Math.max(3.75, reach * margin)
}

export function getSpecParams(spec, overrides = {}) {
  return buildParamMap(spec, overrides)
}

export function validateDrawSpec(spec) {
  return Boolean(spec && typeof spec === 'object' && Array.isArray(spec.commands))
}

/** Canvas trống — trạng thái chờ, không báo lỗi */
export function renderEmptyCanvas(canvas, options = {}) {
  if (!canvas) return
  const cw = options.width ?? DEFAULT_CANVAS.width
  const ch = options.height ?? DEFAULT_CANVAS.height
  const pad = options.padding ?? DEFAULT_CANVAS.padding
  const bg = options.background ?? DEFAULT_CANVAS.background
  const hint = options.hint ?? ''

  canvas.width = cw
  canvas.height = ch
  const ctx = canvas.getContext('2d')
  if (!ctx) return

  ctx.fillStyle = bg
  ctx.fillRect(0, 0, cw, ch)

  const step = 32
  ctx.strokeStyle = 'rgba(226, 232, 240, 0.85)'
  ctx.lineWidth = 1
  for (let x = pad; x < cw - pad; x += step) {
    ctx.beginPath()
    ctx.moveTo(x, pad)
    ctx.lineTo(x, ch - pad)
    ctx.stroke()
  }
  for (let y = pad; y < ch - pad; y += step) {
    ctx.beginPath()
    ctx.moveTo(pad, y)
    ctx.lineTo(cw - pad, y)
    ctx.stroke()
  }

  ctx.strokeStyle = '#e2e8f0'
  ctx.beginPath()
  ctx.moveTo(pad, ch - pad)
  ctx.lineTo(cw - pad, ch - pad)
  ctx.moveTo(pad, pad)
  ctx.lineTo(pad, ch - pad)
  ctx.stroke()

  if (hint) {
    ctx.fillStyle = '#94a3b8'
    ctx.font = '500 15px "Be Vietnam Pro", system-ui, sans-serif'
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText(hint, cw / 2, ch / 2)
  }
}

function normalizeCommand(cmd) {
  if (!cmd || !cmd.op) return cmd
  const c = { ...cmd }
  const op = String(c.op).toLowerCase()
  if (op === 'midpoint3d') c.op = 'midpoint3d'
  if (op === 'centroid3d') c.op = 'centroid3d'
  if (op === 'intersection3d') c.op = 'intersection3d'
  if (
    op === 'pointonsegment' ||
    op === 'point_on_segment' ||
    op === 'pointalong' ||
    op === 'point_along'
  ) {
    c.op = 'point'
    c.from = c.from || c.segment?.[0] || c.on?.[0]
    c.to = c.to || c.segment?.[1] || c.on?.[1]
    c.along = c.along ?? c.ratio ?? c.t ?? 0.5
  }
  if (op === 'projection') c.op = 'foot'
  if (op === 'symmetry') c.op = 'reflect'
  if (c.strokeWidth != null && c.width == null) c.width = c.strokeWidth
  if (c.op === 'foot' && !c.from && c.point) c.from = c.point
  if (c.op === 'reflect' && !c.from && c.point) c.from = c.point
  if (c.op === 'point') {
    c.from = c.from || c.segment?.[0] || c.onSegment?.[0]
    c.to = c.to || c.segment?.[1] || c.onSegment?.[1]
  }
  if (op === 'vector') {
    c.op = 'segment'
    c.arrow = c.arrow !== false
  }
  if (c.op === 'segment' || c.op === 'segment3d' || c.op === 'connect') {
    c.from = c.from || c.a || c.start
    c.to = c.to || c.b || c.end
    if (!c.from && Array.isArray(c.points) && c.points.length >= 2) {
      c.from = c.points[0]
      c.to = c.points[1]
    }
    if (c.vector === true && c.arrow == null) c.arrow = true
  }
  if (c.color && !c.stroke) c.stroke = c.color
  if (c.style === 'dashed') c.dashed = true
  if (c.op === 'polygon' && !c.points && c.vertices) c.points = c.vertices
  if (c.op === 'rightAngle' && Array.isArray(c.arms)) {
    c.leg1 = c.leg1 || c.arms[0]
    c.leg2 = c.leg2 || c.arms[1]
  }
  const opLow = String(c.op || '').toLowerCase()
  if (opLow === 'equalmarks' || opLow === 'segmentmarks') c.op = 'equalMarks'
  if (opLow === 'parallelmark') c.op = 'parallelMark'
  return c
}

function isPointOp(op) {
  return (
    op === 'point' ||
    op === 'point3d' ||
    op === 'midpoint' ||
    op === 'midpoint3d' ||
    op === 'centroid3d' ||
    op === 'intersection' ||
    op === 'intersection3d' ||
    op === 'foot' ||
    op === 'projection' ||
    op === 'reflect' ||
    op === 'symmetry' ||
    op === 'circumcenter'
  )
}

function footOnLine(p, a, b) {
  const dx = b.x - a.x
  const dy = b.y - a.y
  const len2 = dx * dx + dy * dy
  if (len2 < 1e-12) return null
  const t = ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2
  return { x: a.x + t * dx, y: a.y + t * dy }
}

function reflectAcrossLine(p, a, b) {
  const foot = footOnLine(p, a, b)
  if (!foot) return null
  return { x: 2 * foot.x - p.x, y: 2 * foot.y - p.y }
}

function circumcenterFromThree(p1, p2, p3) {
  const ax = p1.x
  const ay = p1.y
  const bx = p2.x
  const by = p2.y
  const cx = p3.x
  const cy = p3.y
  const d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
  if (Math.abs(d) < 1e-8) return null
  const a2 = ax * ax + ay * ay
  const b2 = bx * bx + by * by
  const c2 = cx * cx + cy * cy
  return {
    x: (a2 * (by - cy) + b2 * (cy - ay) + c2 * (ay - by)) / d,
    y: (a2 * (cx - bx) + b2 * (ax - cx) + c2 * (bx - ax)) / d,
  }
}

function lineIntersect(a, b, c, d) {
  const den = (a.x - b.x) * (c.y - d.y) - (a.y - b.y) * (c.x - d.x)
  if (Math.abs(den) < 1e-8) return null
  const t = ((a.x - c.x) * (c.y - d.y) - (a.y - c.y) * (c.x - d.x)) / den
  return { x: a.x + t * (b.x - a.x), y: a.y + t * (b.y - a.y) }
}

function setPoint3d(id, x, y, z, label, points3d, points2d, layout) {
  points3d[id] = { x, y, z, label: label || id }
  points2d[id] = project3d(x, y, z, layout.ox, layout.oy, layout.scale3d)
  points2d[id].label = label || id
}

function linePlaneIntersect3d(a, b, p0, p1, p2) {
  const ux = b.x - a.x
  const uy = b.y - a.y
  const uz = b.z - a.z
  const v1x = p1.x - p0.x
  const v1y = p1.y - p0.y
  const v1z = p1.z - p0.z
  const v2x = p2.x - p0.x
  const v2y = p2.y - p0.y
  const v2z = p2.z - p0.z
  const nx = v1y * v2z - v1z * v2y
  const ny = v1z * v2x - v1x * v2z
  const nz = v1x * v2y - v1y * v2x
  const denom = nx * ux + ny * uy + nz * uz
  if (Math.abs(denom) < 1e-9) return null
  const w0 = p0.x - a.x
  const w1 = p0.y - a.y
  const w2 = p0.z - a.z
  const t = (nx * w0 + ny * w1 + nz * w2) / denom
  return { x: a.x + ux * t, y: a.y + uy * t, z: a.z + uz * t, t }
}

function figureCentroid(points) {
  const vals = Object.values(points || {})
  if (!vals.length) return { x: 0, y: 0 }
  const sx = vals.reduce((s, p) => s + p.x, 0) / vals.length
  const sy = vals.reduce((s, p) => s + p.y, 0) / vals.length
  return { x: sx, y: sy }
}

function outwardFrom(center, p, dist) {
  const pos = outwardLabelPosition(p, center, {}, p?.label || '', dist, 5)
  return { x: pos.x, y: pos.y }
}

/** Đặt nhãn lệch khỏi chấm — tránh đè lên tâm hình (giao chéo, trọng tâm). */
function outwardLabelPosition(p, center, points2d, pointId, dist, radius = 5) {
  const minDist = Math.max(Number(dist) || 18, radius + 13)
  let dx = p.x - center.x
  let dy = p.y - center.y
  let len = Math.hypot(dx, dy)

  if (len < 8) {
    const peers = []
    for (const [id, q] of Object.entries(points2d || {})) {
      if (id === pointId || !q) continue
      const vx = q.x - p.x
      const vy = q.y - p.y
      const d = Math.hypot(vx, vy)
      if (d < 1) continue
      peers.push({ vx: vx / d, vy: vy / d, d })
    }
    peers.sort((a, b) => a.d - b.d)
    if (peers.length >= 2) {
      let bx = peers[0].vx + peers[1].vx
      let by = peers[0].vy + peers[1].vy
      len = Math.hypot(bx, by)
      if (len > 0.2) {
        dx = bx / len
        dy = by / len
      }
    }
    if (len < 0.2 && peers.length) {
      dx = -peers[0].vx
      dy = -peers[0].vy
      len = 1
    }
    if (len < 0.2) {
      const seed = [...String(pointId || 'P')].reduce((s, c) => s + c.charCodeAt(0), 69)
      const ang = ((seed * 53) % 360) * (Math.PI / 180) - Math.PI / 4
      dx = Math.cos(ang)
      dy = Math.sin(ang)
    }
  } else {
    dx /= len
    dy /= len
  }

  return {
    x: p.x + dx * minDist,
    y: p.y + dy * minDist,
    dx,
    dy,
  }
}

function edgeOutwardLabel(a, b, p, centroid, dist) {
  let nx = -(b.y - a.y)
  let ny = b.x - a.x
  const len = Math.hypot(nx, ny) || 1
  nx /= len
  ny /= len
  const vx = p.x - centroid.x
  const vy = p.y - centroid.y
  if (nx * vx + ny * vy < 0) {
    nx = -nx
    ny = -ny
  }
  return { x: p.x + nx * dist, y: p.y + ny * dist }
}

function tryResolvePoint(cmd, points2d, points3d, pmap, layout) {
  const op = cmd.op
  if (op === 'midpoint') {
    const from = cmd.from || cmd.a
    const to = cmd.to || cmd.b
    const id = cmd.id
    if (!id || !from || !to || points2d[id]) return Boolean(points2d[id])
    const a = points2d[from]
    const b = points2d[to]
    if (!a || !b) return false
    points2d[id] = {
      x: (a.x + b.x) / 2,
      y: (a.y + b.y) / 2,
      label: cmd.label || id,
    }
    return true
  }

  if (op === 'intersection') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    const l1 = cmd.line1 || []
    const l2 = cmd.line2 || []
    if (l1.length < 2 || l2.length < 2) return false
    const p1 = points2d[l1[0]]
    const p2 = points2d[l1[1]]
    const p3 = points2d[l2[0]]
    const p4 = points2d[l2[1]]
    if (!p1 || !p2 || !p3 || !p4) return false
    const hit = lineIntersect(p1, p2, p3, p4)
    if (!hit) return false
    points2d[id] = { x: hit.x, y: hit.y, label: cmd.label || id }
    return true
  }

  if (op === 'point3d') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    setPoint3d(
      id,
      resolveNumber(cmd.x, pmap),
      resolveNumber(cmd.y, pmap),
      resolveNumber(cmd.z, pmap),
      cmd.label || id,
      points3d,
      points2d,
      layout,
    )
    return true
  }

  if (op === 'midpoint3d') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    const from = cmd.from || cmd.a
    const to = cmd.to || cmd.b
    const a = points3d[from]
    const b = points3d[to]
    if (!a || !b) return false
    setPoint3d(
      id,
      (a.x + b.x) / 2,
      (a.y + b.y) / 2,
      (a.z + b.z) / 2,
      cmd.label || id,
      points3d,
      points2d,
      layout,
    )
    return true
  }

  if (op === 'centroid3d') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    const through = cmd.through || cmd.points || []
    const verts = through.map((pid) => points3d[pid]).filter(Boolean)
    if (verts.length < 3) return false
    const sx = verts.reduce((s, p) => s + p.x, 0) / verts.length
    const sy = verts.reduce((s, p) => s + p.y, 0) / verts.length
    const sz = verts.reduce((s, p) => s + p.z, 0) / verts.length
    setPoint3d(id, sx, sy, sz, cmd.label || id, points3d, points2d, layout)
    return true
  }

  if (op === 'intersection3d') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    const line = cmd.line || cmd.line1 || []
    const plane = cmd.plane || cmd.through || []
    if (line.length < 2 || plane.length < 3) return false
    const a = points3d[line[0]]
    const b = points3d[line[1]]
    const p0 = points3d[plane[0]]
    const p1 = points3d[plane[1]]
    const p2 = points3d[plane[2]]
    if (!a || !b || !p0 || !p1 || !p2) return false
    const hit = linePlaneIntersect3d(a, b, p0, p1, p2)
    if (!hit) return false
    setPoint3d(id, hit.x, hit.y, hit.z, cmd.label || id, points3d, points2d, layout)
    return true
  }

  if (op === 'foot' || op === 'projection') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    const fromId = cmd.from || cmd.point
    const line = cmd.line || cmd.onto || []
    const l0 = line[0] || cmd.lineFrom
    const l1 = line[1] || cmd.lineTo
    if (!fromId || !l0 || !l1) return false
    const p = points2d[fromId]
    const a = points2d[l0]
    const b = points2d[l1]
    if (!p || !a || !b) return false
    const hit = footOnLine(p, a, b)
    if (!hit) return false
    points2d[id] = { x: hit.x, y: hit.y, label: cmd.label || id }
    return true
  }

  if (op === 'reflect' || op === 'symmetry') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    const fromId = cmd.from || cmd.point
    const line = cmd.across || cmd.line || []
    const l0 = line[0] || cmd.lineFrom
    const l1 = line[1] || cmd.lineTo
    if (!fromId || !l0 || !l1) return false
    const p = points2d[fromId]
    const a = points2d[l0]
    const b = points2d[l1]
    if (!p || !a || !b) return false
    const hit = reflectAcrossLine(p, a, b)
    if (!hit) return false
    points2d[id] = { x: hit.x, y: hit.y, label: cmd.label || id }
    return true
  }

  if (op === 'circumcenter') {
    const id = cmd.id
    if (!id || points2d[id]) return Boolean(points2d[id])
    const through = cmd.through || cmd.points || []
    const p1 = points2d[through[0] || cmd.p1]
    const p2 = points2d[through[1] || cmd.p2]
    const p3 = points2d[through[2] || cmd.p3]
    if (!p1 || !p2 || !p3) return false
    const hit = circumcenterFromThree(p1, p2, p3)
    if (!hit) return false
    points2d[id] = { x: hit.x, y: hit.y, label: cmd.label || id }
    return true
  }

  if (op !== 'point') return false
  const id = cmd.id
  if (!id || points2d[id]) return Boolean(points2d[id])

  let x
  let y

  const segFrom = cmd.from || cmd.onSegment?.[0]
  const segTo = cmd.to || cmd.onSegment?.[1]
  if (segFrom && segTo && (cmd.along != null || cmd.ratio != null || cmd.t != null)) {
    const a = points2d[segFrom]
    const b = points2d[segTo]
    if (!a || !b) return false
    const t = resolveNumber(cmd.along ?? cmd.ratio ?? cmd.t, pmap)
    x = a.x + t * (b.x - a.x)
    y = a.y + t * (b.y - a.y)
    points2d[id] = { x, y, label: cmd.label || id }
    return true
  }

  if (cmd.base) {
    const base = points2d[cmd.base]
    if (!base) return false
    if (cmd.dist != null || cmd.angleDeg != null) {
      const dist = resolveNumber(cmd.dist ?? cmd.r ?? cmd.dx ?? 0, pmap)
      const ang = (resolveNumber(cmd.angleDeg ?? 0, pmap) * Math.PI) / 180
      x = base.x + dist * Math.cos(ang)
      y = base.y + dist * Math.sin(ang)
    } else {
      x = base.x + resolveNumber(cmd.dx ?? 0, pmap)
      y = base.y + resolveNumber(cmd.dy ?? 0, pmap)
    }
  } else {
    x = resolveNumber(cmd.x, pmap)
    y = resolveNumber(cmd.y, pmap)
  }

  points2d[id] = { x, y, label: cmd.label || id }
  return true
}

function resolveAllPoints(commands, points2d, points3d, pmap, layout) {
  const pointCmds = commands.map(normalizeCommand).filter((c) => c && isPointOp(c.op))
  for (let pass = 0; pass < 16; pass += 1) {
    let progress = false
    for (const cmd of pointCmds) {
      if (tryResolvePoint(cmd, points2d, points3d, pmap, layout)) progress = true
    }
    if (!progress) break
  }
}

/**
 * @param {HTMLCanvasElement} canvas
 * @param {object} spec
 * @param {Record<string, number>} [paramOverrides]
 */
export function renderDrawSpec(canvas, spec, paramOverrides = {}, view = null, renderOptions = {}) {
  if (!canvas || !validateDrawSpec(spec)) return { points: {}, params: {} }
  const ctx = canvas.getContext('2d')
  if (!ctx) return { points: {}, params: {} }

  const cw = spec.canvas?.width || DEFAULT_CANVAS.width
  const ch = spec.canvas?.height || DEFAULT_CANVAS.height
  const pad = spec.canvas?.padding ?? DEFAULT_CANVAS.padding
  const bg = spec.canvas?.background || DEFAULT_CANVAS.background

  canvas.width = cw
  canvas.height = ch

  const pmap = buildParamMap(spec, paramOverrides)
  const extraPlanes = Array.isArray(renderOptions.planes) ? renderOptions.planes : []
  const points2d = {}
  const points3d = {}
  const mode = spec.mode === '3d' ? '3d' : '2d'
  const layout = {
    ox: cw / 2,
    oy: ch * 0.52,
    scale3d: Math.min(cw, ch) / 6,
    orbitIso: mode === '3d',
  }

  const commands = [...spec.commands.map(normalizeCommand), ...extraPlanes.map(normalizeCommand)]

  resolveAllPoints(commands, points2d, points3d, pmap, layout)
  if (mode === '3d' && Object.keys(points3d).length) {
    center3dLayout(points3d, points2d, layout, cw, ch, pad, view)
  }
  const model2d = {}
  for (const [id, p] of Object.entries(points2d)) {
    if (points3d[id]) {
      model2d[id] = {
        x: points3d[id].x,
        y: points3d[id].y,
        label: p.label,
      }
    } else {
      model2d[id] = { x: p.x, y: p.y, label: p.label }
    }
  }
  layout.fit2d = null
  if (mode === '2d') {
    layout.fit2d = fit2dModelToCanvas(model2d, points2d, cw, ch, pad, commands, pmap)
  }
  if (view) applyViewToPoints(points2d, model2d, points3d, layout, view, mode)
  const centroid = figureCentroid(points2d)
  const planeHalfMin = mode === '3d' && Object.keys(points3d).length ? suggestedPlaneHalf(points3d) : null
  const planeCmds = commands.filter((c) => c?.op === 'plane')
  let legacyUniformPlaneBase = null
  if (planeCmds.length >= 2) {
    const sizes = planeCmds
      .map((c) => resolveNumber(c.size ?? c.half, pmap))
      .filter((n) => Number.isFinite(n))
    if (
      sizes.length === planeCmds.length &&
      sizes.every((s) => Math.abs(s - sizes[0]) < 0.05) &&
      sizes[0] >= 4 &&
      sizes[0] <= 7
    ) {
      legacyUniformPlaneBase = sizes[0]
    }
  }

  ctx.clearRect(0, 0, cw, ch)
  ctx.fillStyle = bg
  ctx.fillRect(0, 0, cw, ch)

  const pointStyles = {}
  for (const cmd of commands) {
    if (cmd?.id && isPointOp(cmd.op)) pointStyles[cmd.id] = cmd
  }

  function modelCenter3d() {
    return orbitCenterFromModel(model2d, points3d)
  }

  function screenFromModel(x, y, z) {
    if (view) {
      const c = modelCenter3d()
      return orbitModelPoint(x, y, z, c, view, layout)
    }
    if (mode === '3d' || layout.orbitIso) {
      return project3d(x, y, z, layout.ox, layout.oy, layout.scale3d)
    }
    return { x, y }
  }

  function drawPlane(cmd) {
    const which = String(cmd.which || cmd.plane || 'xy').toLowerCase()
    const theme = PLANE_THEMES[which] || PLANE_THEMES.xy
    let half
    if (legacyUniformPlaneBase != null) {
      half = which === 'xy' ? legacyUniformPlaneBase * PLANE_XY_FIT_FACTOR : legacyUniformPlaneBase / 4
    } else {
      half = resolveNumber(cmd.size ?? cmd.half ?? PLANE_DEFAULT_HALF[which] ?? PLANE_BASE_HALF, pmap)
    }
    if (which === 'xy' && planeHalfMin != null) {
      half = Math.max(half, planeHalfMin * PLANE_XY_FIT_FACTOR)
    }
    const step = resolveNumber(cmd.step ?? 0.5, pmap)
    const ox = resolveNumber(cmd.ox ?? 0, pmap)
    const oy = resolveNumber(cmd.oy ?? 0, pmap)
    const oz = resolveNumber(cmd.oz ?? 0, pmap)
    const lines = []
    const pushLine = (x1, y1, z1, x2, y2, z2) => {
      const a = screenFromModel(x1, y1, z1)
      const b = screenFromModel(x2, y2, z2)
      lines.push(a, b)
    }
    if (which === 'xy') {
      for (let u = -half; u <= half + 1e-6; u += step) {
        pushLine(ox - half, oy + u, oz, ox + half, oy + u, oz)
        pushLine(ox + u, oy - half, oz, ox + u, oy + half, oz)
      }
    } else if (which === 'xz') {
      for (let u = -half; u <= half + 1e-6; u += step) {
        pushLine(ox - half, oy, oz + u, ox + half, oy, oz + u)
        pushLine(ox + u, oy, oz - half, ox + u, oy, oz + half)
      }
    } else {
      for (let u = -half; u <= half + 1e-6; u += step) {
        pushLine(ox, oy - half, oz + u, ox, oy + half, oz + u)
        pushLine(ox, oy + u, oz - half, ox, oy + u, oz + half)
      }
    }
    const use3dTheme = mode === '3d' || layout.orbitIso
    ctx.save()
    ctx.globalAlpha = PLANE_GRID_ALPHA
    ctx.strokeStyle = planeStyleField(cmd, 'stroke', theme, use3dTheme, '#cbd5e1')
    ctx.lineWidth = cmd.width ?? 0.65
    for (let i = 0; i < lines.length; i += 2) {
      ctx.beginPath()
      ctx.moveTo(lines[i].x, lines[i].y)
      ctx.lineTo(lines[i + 1].x, lines[i + 1].y)
      ctx.stroke()
    }
    let fill = planeStyleField(cmd, 'fill', theme, use3dTheme, undefined)
    if (fill === undefined && use3dTheme) fill = theme.fill
    if (fill && fill !== 'none') {
      ctx.globalAlpha = PLANE_FILL_ALPHA
      let p1
      let p2
      let p3
      let p4
      if (which === 'xy') {
        p1 = screenFromModel(ox - half, oy - half, oz)
        p2 = screenFromModel(ox + half, oy - half, oz)
        p3 = screenFromModel(ox + half, oy + half, oz)
        p4 = screenFromModel(ox - half, oy + half, oz)
      } else if (which === 'xz') {
        p1 = screenFromModel(ox - half, oy, oz - half)
        p2 = screenFromModel(ox + half, oy, oz - half)
        p3 = screenFromModel(ox + half, oy, oz + half)
        p4 = screenFromModel(ox - half, oy, oz + half)
      } else {
        p1 = screenFromModel(ox, oy - half, oz - half)
        p2 = screenFromModel(ox, oy + half, oz - half)
        p3 = screenFromModel(ox, oy + half, oz + half)
        p4 = screenFromModel(ox, oy - half, oz + half)
      }
      ctx.fillStyle = fill
      ctx.beginPath()
      ctx.moveTo(p1.x, p1.y)
      ctx.lineTo(p2.x, p2.y)
      ctx.lineTo(p3.x, p3.y)
      ctx.lineTo(p4.x, p4.y)
      ctx.closePath()
      ctx.fill()
    }
    const label = cmd.label || (which === 'xy' ? 'XY' : which === 'xz' ? 'XZ' : 'YZ')
    const lc = screenFromModel(ox + half * 0.72, oy + half * 0.72, which === 'xy' ? oz : which === 'xz' ? oz + half * 0.5 : oz)
    ctx.globalAlpha = PLANE_LABEL_ALPHA
    ctx.fillStyle = planeStyleField(cmd, 'color', theme, use3dTheme, '#94a3b8')
    ctx.font = '600 11px "Be Vietnam Pro", system-ui, sans-serif'
    ctx.fillText(label, lc.x + 4, lc.y - 4)
    ctx.restore()
  }

  function exec(cmd) {
    const op = cmd.op

    if (op === 'plane') {
      drawPlane(cmd)
      return
    }

    if (op === 'grid') {
      const step = resolveNumber(cmd.step ?? 24, pmap)
      ctx.strokeStyle = cmd.color || '#e2e8f0'
      ctx.lineWidth = 1
      for (let x = pad; x < cw - pad; x += step) {
        ctx.beginPath()
        ctx.moveTo(x, pad)
        ctx.lineTo(x, ch - pad)
        ctx.stroke()
      }
      for (let y = pad; y < ch - pad; y += step) {
        ctx.beginPath()
        ctx.moveTo(pad, y)
        ctx.lineTo(cw - pad, y)
        ctx.stroke()
      }
      return
    }

    if (op === 'axes') {
      const ax = resolveNumber(cmd.ox ?? cw / 2, pmap)
      const ay = resolveNumber(cmd.oy ?? ch - pad, pmap)
      ctx.strokeStyle = '#cbd5e1'
      ctx.lineWidth = 1
      ctx.beginPath()
      ctx.moveTo(pad, ay)
      ctx.lineTo(cw - pad, ay)
      ctx.moveTo(ax, pad)
      ctx.lineTo(ax, ch - pad)
      ctx.stroke()
      return
    }

    if (isPointOp(op)) return

    if (op === 'connect') {
      const ids = cmd.points || cmd.path || []
      const pts = ids.map((id) => (typeof id === 'string' ? points2d[id] : null)).filter(Boolean)
      for (let i = 0; i < pts.length - 1; i += 1) {
        strokeSegment(ctx, pts[i], pts[i + 1], cmd)
      }
      return
    }

    if (op === 'segment' || op === 'segment3d') {
      const chain = Array.isArray(cmd.points) ? cmd.points : null
      if (chain && chain.length >= 2) {
        for (let i = 0; i < chain.length - 1; i += 1) {
          const a = points2d[chain[i]]
          const b = points2d[chain[i + 1]]
          if (a && b) strokeSegment(ctx, a, b, cmd)
        }
        return
      }
      const a = points2d[cmd.from]
      const b = points2d[cmd.to]
      if (!a || !b) return
      strokeSegment(ctx, a, b, cmd)
      return
    }

    if (op === 'line') {
      ctx.strokeStyle = cmd.stroke || '#0f172a'
      ctx.lineWidth = cmd.width ?? 2
      ctx.lineCap = 'round'
      let p1 = { x: resolveNumber(cmd.x1, pmap), y: resolveNumber(cmd.y1, pmap) }
      let p2 = { x: resolveNumber(cmd.x2, pmap), y: resolveNumber(cmd.y2, pmap) }
      if (layout.fit2d) {
        p1 = mapFit2dPoint(p1.x, p1.y, layout.fit2d)
        p2 = mapFit2dPoint(p2.x, p2.y, layout.fit2d)
      }
      ctx.beginPath()
      ctx.moveTo(p1.x, p1.y)
      ctx.lineTo(p2.x, p2.y)
      ctx.stroke()
      return
    }

    if (op === 'polygon') {
      const pts = (cmd.points || [])
        .map((pid) => (typeof pid === 'string' ? points2d[pid] : null))
        .filter(Boolean)
      if (pts.length < 2) return
      ctx.beginPath()
      ctx.moveTo(pts[0].x, pts[0].y)
      for (let i = 1; i < pts.length; i += 1) ctx.lineTo(pts[i].x, pts[i].y)
      if (cmd.closed !== false) ctx.closePath()
      if (cmd.fill && cmd.fill !== 'none') {
        ctx.fillStyle = cmd.fill
        ctx.fill()
      }
      ctx.strokeStyle = cmd.stroke || '#0f172a'
      ctx.lineWidth = cmd.width ?? 2
      ctx.stroke()
      return
    }

    if (op === 'circle') {
      let cx
      let cy
      if (cmd.center && points2d[cmd.center]) {
        cx = points2d[cmd.center].x
        cy = points2d[cmd.center].y
      } else {
        let px = resolveNumber(cmd.cx, pmap)
        let py = resolveNumber(cmd.cy, pmap)
        if (layout.fit2d) ({ x: px, y: py } = mapFit2dPoint(px, py, layout.fit2d))
        cx = px
        cy = py
      }
      let r = resolveNumber(cmd.r ?? cmd.radius, pmap)
      if (cmd.through && points2d[cmd.through] && cmd.center && points2d[cmd.center]) {
        const o = points2d[cmd.center]
        const p = points2d[cmd.through]
        r = Math.hypot(p.x - o.x, p.y - o.y)
      } else if (layout.fit2d?.applied) {
        r *= layout.fit2d.scale
      }
      if (!(r > 0)) return
      ctx.beginPath()
      ctx.arc(cx, cy, r, 0, Math.PI * 2)
      if (cmd.fill && cmd.fill !== 'none') {
        ctx.fillStyle = cmd.fill
        ctx.fill()
      }
      ctx.strokeStyle = cmd.stroke || '#2563eb'
      ctx.lineWidth = cmd.width ?? 2
      ctx.setLineDash(cmd.dashed ? [6, 4] : [])
      ctx.stroke()
      ctx.setLineDash([])
      return
    }

    if (op === 'arc') {
      let c =
        cmd.center && points2d[cmd.center]
          ? points2d[cmd.center]
          : { x: resolveNumber(cmd.cx, pmap), y: resolveNumber(cmd.cy, pmap) }
      if (!cmd.center && layout.fit2d) {
        c = mapFit2dPoint(c.x, c.y, layout.fit2d)
      }
      let r = resolveNumber(cmd.r, pmap)
      if (layout.fit2d?.applied && cmd.r != null) r *= layout.fit2d.scale
      const s = (resolveNumber(cmd.startDeg, pmap) * Math.PI) / 180
      const e = (resolveNumber(cmd.endDeg, pmap) * Math.PI) / 180
      ctx.strokeStyle = cmd.stroke || '#64748b'
      ctx.lineWidth = cmd.width ?? 1.5
      ctx.beginPath()
      ctx.arc(c.x, c.y, r, s, e)
      ctx.stroke()
      return
    }

    if (op === 'sideLabel') {
      const a = points2d[cmd.from]
      const b = points2d[cmd.to]
      if (!a || !b) return
      const off = resolveNumber(cmd.offset ?? 22, pmap)
      const pos =
        cmd.outward !== false
          ? edgeOutwardLabel(a, b, { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }, centroid, off)
          : { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }
      const text = String(cmd.text ?? '')
      ctx.fillStyle = cmd.color || '#0f172a'
      ctx.font = cmd.font || '700 14px "Be Vietnam Pro", system-ui, sans-serif'
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      ctx.fillText(text, pos.x, pos.y)
      ctx.textAlign = 'left'
      ctx.textBaseline = 'alphabetic'
      return
    }

    if (op === 'angleMark') {
      const v = points2d[cmd.vertex]
      const p1 = points2d[cmd.from || cmd.p1 || cmd.leg1]
      const p2 = points2d[cmd.to || cmd.p2 || cmd.leg2]
      if (!v || !p1 || !p2) return
      const r = resolveNumber(cmd.radius ?? 26, pmap)
      let a1 = Math.atan2(p1.y - v.y, p1.x - v.x)
      let a2 = Math.atan2(p2.y - v.y, p2.x - v.x)
      let diff = a2 - a1
      while (diff <= -Math.PI) diff += Math.PI * 2
      while (diff > Math.PI) diff -= Math.PI * 2
      ctx.strokeStyle = cmd.stroke || '#2563eb'
      ctx.lineWidth = cmd.width ?? 2
      const arcCount = Math.max(1, Math.min(3, Number(cmd.arcs ?? cmd.arcCount ?? 1)))
      for (let ai = 0; ai < arcCount; ai += 1) {
        ctx.beginPath()
        ctx.arc(v.x, v.y, r - ai * 5, a1, a1 + diff, diff < 0)
        ctx.stroke()
      }
      let mid = a1 + diff / 2
      if (cmd.tick || cmd.markTick) {
        const rm = r - (arcCount - 1) * 2.5
        const px = v.x + Math.cos(mid) * rm
        const py = v.y + Math.sin(mid) * rm
        const tx = -Math.sin(mid)
        const ty = Math.cos(mid)
        const h = 5
        ctx.beginPath()
        ctx.moveTo(px - tx * h, py - ty * h)
        ctx.lineTo(px + tx * h, py + ty * h)
        ctx.stroke()
      }
      let lx = v.x + Math.cos(mid) * (r + 20)
      let ly = v.y + Math.sin(mid) * (r + 20)
      const awayId = cmd.labelAwayFrom
      if (awayId && points2d[awayId]) {
        const o = points2d[awayId]
        const bx = lx - v.x
        const by = ly - v.y
        const ox = o.x - v.x
        const oy = o.y - v.y
        if (bx * ox + by * oy > 0) {
          mid += Math.PI
          lx = v.x + Math.cos(mid) * (r + 20)
          ly = v.y + Math.sin(mid) * (r + 20)
        }
      }
      let label = String(cmd.label ?? '')
        .replace(/\$+/g, '')
        .replace(/\\circ/g, '°')
      if (!label && (cmd.angleDeg != null || cmd.degrees != null)) {
        label = `${Number(cmd.angleDeg ?? cmd.degrees)}°`
      }
      if (label) {
        ctx.fillStyle = cmd.color || '#1d4ed8'
        ctx.font = cmd.font || '700 13px "Be Vietnam Pro", system-ui, sans-serif'
        ctx.textAlign = 'center'
        ctx.textBaseline = 'middle'
        ctx.fillText(label, lx, ly)
        ctx.textAlign = 'left'
        ctx.textBaseline = 'alphabetic'
      }
      return
    }

    if (op === 'equalmarks' || op === 'equalMarks' || op === 'segmentMarks') {
      const style = cmd.style || cmd.tickStyle || 'tick'
      const mark = Number(cmd.mark ?? 1)
      const along = (mark - 1) * 0.06
      const segs = cmd.segments || cmd.pairs || []
      for (const pair of segs) {
        if (!Array.isArray(pair) || pair.length < 2) continue
        const a = points2d[pair[0]]
        const b = points2d[pair[1]]
        if (a && b) drawSegmentEqualMark(ctx, a, b, style, along)
      }
      return
    }

    if (op === 'parallelmark' || op === 'parallelMark') {
      const a = points2d[cmd.from]
      const b = points2d[cmd.to]
      if (!a || !b) return
      drawParallelChevrons(ctx, a, b, cmd.count ?? cmd.chevrons ?? 1)
      return
    }

    if (op === 'label') {
      let x
      let y
      const text = String(cmd.text ?? '')
        .replace(/\$+/g, '')
        .replace(/\\circ/g, '°')
        .replace(/\\[a-zA-Z]+/g, '')
      if (cmd.at && points2d[cmd.at]) {
        const base = points2d[cmd.at]
        const dx = resolveNumber(cmd.dx ?? 0, pmap)
        const dy = resolveNumber(cmd.dy ?? 0, pmap)
        if (dx === 0 && dy === 0 && cmd.at === 'O') {
          const o = outwardFrom(centroid, base, 36)
          x = o.x + 24
          y = o.y + 4
        } else {
          x = base.x + dx
          y = base.y + dy
        }
      } else {
        x = resolveNumber(cmd.x, pmap)
        y = resolveNumber(cmd.y, pmap)
        if (layout.fit2d) ({ x, y } = mapFit2dPoint(x, y, layout.fit2d))
      }
      ctx.fillStyle = cmd.color || '#475569'
      ctx.font = cmd.font || '600 13px "Be Vietnam Pro", system-ui, sans-serif'
      ctx.fillText(text, x, y)
      return
    }

    if (op === 'rightAngle') {
      const v = points2d[cmd.vertex]
      const arms = Array.isArray(cmd.arms) ? cmd.arms : null
      const p1 = points2d[cmd.leg1 || cmd.from || cmd.p1 || arms?.[0]]
      const p2 = points2d[cmd.leg2 || cmd.to || cmd.p2 || arms?.[1]]
      if (!v || !p1 || !p2) return
      const sz = resolveNumber(cmd.size ?? 14, pmap)
      const u1 = norm(sub(p1, v))
      const u2 = norm(sub(p2, v))
      const c1 = add(v, mul(u1, sz))
      const c2 = add(v, mul(u2, sz))
      const corner = add(c1, mul(u2, sz))
      ctx.strokeStyle = cmd.stroke || '#94a3b8'
      ctx.lineWidth = 1.5
      ctx.beginPath()
      ctx.moveTo(c1.x, c1.y)
      ctx.lineTo(corner.x, corner.y)
      ctx.lineTo(c2.x, c2.y)
      ctx.stroke()
    }

    if (op === 'box3d') {
      const o = cmd.origin || [0, 0, 0]
      const sx = resolveNumber(cmd.size?.[0] ?? cmd.sx ?? 1, pmap)
      const sy = resolveNumber(cmd.size?.[1] ?? cmd.sy ?? 1, pmap)
      const sz = resolveNumber(cmd.size?.[2] ?? cmd.sz ?? 1, pmap)
      const s = [sx, sy, sz]
      const raw = [
        [o[0], o[1], o[2]],
        [o[0] + s[0], o[1], o[2]],
        [o[0] + s[0], o[1] + s[1], o[2]],
        [o[0], o[1] + s[1], o[2]],
        [o[0], o[1], o[2] + s[2]],
        [o[0] + s[0], o[1], o[2] + s[2]],
        [o[0] + s[0], o[1] + s[1], o[2] + s[2]],
        [o[0], o[1] + s[1], o[2] + s[2]],
      ]
      const corners = raw.map(([x, y, z]) => screenFromModel(x, y, z))
      const edges = [
        [0, 1], [1, 2], [2, 3], [3, 0],
        [4, 5], [5, 6], [6, 7], [7, 4],
        [0, 4], [1, 5], [2, 6], [3, 7],
      ]
      ctx.strokeStyle = cmd.stroke || '#0f172a'
      ctx.lineWidth = cmd.width ?? 2
      for (const [i, j] of edges) {
        ctx.beginPath()
        ctx.moveTo(corners[i].x, corners[i].y)
        ctx.lineTo(corners[j].x, corners[j].y)
        ctx.stroke()
      }
      if (cmd.faceLabels !== false) {
        const L = cmd.labels || {}
        const faceDefs = [
          { text: L.bottom || 'Đáy', pt: [0, 1, 2, 3] },
          { text: L.top || 'Nóc', pt: [4, 5, 6, 7] },
          { text: L.front || 'Trước', pt: [0, 1, 5, 4] },
          { text: L.back || 'Sau', pt: [2, 3, 7, 6] },
          { text: L.right || 'Phải', pt: [1, 2, 6, 5] },
          { text: L.left || 'Trái', pt: [0, 3, 7, 4] },
        ]
        ctx.font = '600 11px "Be Vietnam Pro", system-ui, sans-serif'
        ctx.fillStyle = cmd.labelColor || '#64748b'
        for (const f of faceDefs) {
          let sx = 0
          let sy = 0
          for (const i of f.pt) {
            sx += corners[i].x
            sy += corners[i].y
          }
          sx /= f.pt.length
          sy /= f.pt.length
          ctx.fillText(f.text, sx, sy)
        }
      }
    }
  }

  for (const cmd of commands) {
    if (cmd?.op === 'grid' || cmd?.op === 'axes' || cmd?.op === 'plane') exec(cmd)
  }
  for (const cmd of commands) {
    const op = cmd?.op
    if (
      op &&
      !isPointOp(op) &&
      op !== 'grid' &&
      op !== 'axes' &&
      op !== 'plane' &&
      op !== 'label' &&
      op !== 'angleMark' &&
      op !== 'rightAngle' &&
      op !== 'sideLabel' &&
      op !== 'equalMarks' &&
      op !== 'parallelMark' &&
      op !== 'connect'
    ) {
      exec(cmd)
    }
  }
  for (const cmd of commands) {
    if (cmd?.op === 'connect') exec(cmd)
  }
  for (const cmd of commands) {
    const op = cmd?.op
    if (
      op === 'sideLabel' ||
      op === 'angleMark' ||
      op === 'rightAngle' ||
      op === 'label' ||
      op === 'equalMarks' ||
      op === 'parallelMark'
    ) {
      exec(cmd)
    }
  }

  const pointLabelItems = []
  for (const [id, p] of Object.entries(points2d)) {
    const cmd = pointStyles[id] || { id }
    const item = computePointLabelLayout(p, cmd, { centroid, points2d })
    if (item) pointLabelItems.push(item)
    drawPointDot(ctx, p, cmd)
  }
  separatePointLabelPositions(pointLabelItems)
  for (const item of pointLabelItems) {
    drawPointLabelText(ctx, item)
  }

  return { points: points2d, params: pmap }
}

function separatePointLabelPositions(items, minGap = 26) {
  if (items.length < 2) return
  for (let iter = 0; iter < 16; iter += 1) {
    let moved = false
    for (let i = 0; i < items.length; i += 1) {
      const a = items[i]
      const ad = Math.hypot(a.lx - a.px, a.ly - a.py)
      if (ad < a.minAnchor) {
        const ux = (a.lx - a.px) / (ad || 1)
        const uy = (a.ly - a.py) / (ad || 1)
        a.lx = a.px + ux * a.minAnchor
        a.ly = a.py + uy * a.minAnchor
        moved = true
      }
      for (let j = i + 1; j < items.length; j += 1) {
        const b = items[j]
        const dx = b.lx - a.lx
        const dy = b.ly - a.ly
        const d = Math.hypot(dx, dy)
        if (d >= minGap) continue
        const push = (minGap - d) / 2 + 0.5
        const ux = dx / (d || 1)
        const uy = dy / (d || 1)
        a.lx -= ux * push
        a.ly -= uy * push
        b.lx += ux * push
        b.ly += uy * push
        a.alignDx = a.lx - a.px
        a.alignDy = a.ly - a.py
        b.alignDx = b.lx - b.px
        b.alignDy = b.ly - b.py
        moved = true
      }
    }
    if (!moved) break
  }
}

function computePointLabelLayout(p, cmd, layout) {
  const r = cmd.radius ?? 5
  const label = String(p.label || cmd.label || cmd.id || '').replace(/_circ/gi, '')
  if (!label) return null

  const centroid = layout?.centroid || { x: p.x, y: p.y }
  const points2d = layout?.points2d || {}
  let lx
  let ly
  let alignDx = 0
  let alignDy = 0
  const minAnchor = r + 14

  if (cmd.id === 'O') {
    lx = p.x
    ly = p.y - (cmd.labelDist ?? 22)
    alignDy = -1
  } else if ((cmd.op === 'foot' || cmd.op === 'projection') && cmd.line?.length >= 2) {
    const a = points2d[cmd.line[0]]
    const b = points2d[cmd.line[1]]
    if (a && b) {
      ;({ x: lx, y: ly } = edgeOutwardLabel(a, b, p, centroid, cmd.labelDist ?? 22))
      alignDx = lx - p.x
      alignDy = ly - p.y
    } else {
      const pos = outwardLabelPosition(p, centroid, points2d, cmd.id || label, 24, r)
      lx = pos.x
      ly = pos.y
      alignDx = pos.dx
      alignDy = pos.dy
    }
  } else if (cmd.op === 'midpoint' && cmd.from && cmd.to && points2d[cmd.from] && points2d[cmd.to]) {
    ;({ x: lx, y: ly } = edgeOutwardLabel(points2d[cmd.from], points2d[cmd.to], p, centroid, 20))
    alignDx = lx - p.x
    alignDy = ly - p.y
  } else if (cmd.op === 'intersection' || cmd.line1 || cmd.line2) {
    const pos = outwardLabelPosition(p, centroid, points2d, cmd.id || label, cmd.labelDist ?? 24, r)
    lx = pos.x
    ly = pos.y
    alignDx = pos.dx
    alignDy = pos.dy
  } else {
    const pos = outwardLabelPosition(
      p,
      centroid,
      points2d,
      cmd.id || p.label || label,
      cmd.labelDist ?? (cmd.labelOutward ? 24 : 22),
      r,
    )
    lx = pos.x
    ly = pos.y
    alignDx = pos.dx
    alignDy = pos.dy
  }

  return {
    px: p.x,
    py: p.y,
    lx,
    ly,
    alignDx,
    alignDy,
    label,
    cmd,
    minAnchor,
  }
}

function drawPointDot(ctx, p, cmd) {
  const r = cmd.radius ?? 5
  const onCircle = cmd.onCircle || cmd.highlight === 'circle'
  if (onCircle) {
    ctx.strokeStyle = '#fdba74'
    ctx.lineWidth = 1.25
    ctx.setLineDash([3, 3])
    ctx.beginPath()
    ctx.arc(p.x, p.y, r + 3, 0, Math.PI * 2)
    ctx.stroke()
    ctx.setLineDash([])
  }
  ctx.fillStyle = cmd.fill || (onCircle ? '#fb923c' : '#3b82f6')
  ctx.beginPath()
  ctx.arc(p.x, p.y, r, 0, Math.PI * 2)
  ctx.fill()
}

function drawPointLabelText(ctx, item) {
  const cmd = item.cmd || {}
  ctx.fillStyle = cmd.id === 'O' ? '#2563eb' : '#0f172a'
  ctx.font =
    cmd.id === 'O'
      ? '700 13px "Be Vietnam Pro", system-ui, sans-serif'
      : '600 12px "Be Vietnam Pro", system-ui, sans-serif'
  const ndx = item.alignDx || item.lx - item.px
  const ndy = item.alignDy || item.ly - item.py
  ctx.textAlign = ndx > 4 ? 'left' : ndx < -4 ? 'right' : 'center'
  ctx.textBaseline = ndy > 4 ? 'top' : ndy < -4 ? 'bottom' : 'middle'
  ctx.fillText(item.label, item.lx, item.ly)
  ctx.textAlign = 'left'
  ctx.textBaseline = 'alphabetic'
}

function segPerpUnit(a, b) {
  let nx = -(b.y - a.y)
  let ny = b.x - a.x
  const len = Math.hypot(nx, ny) || 1
  return { nx: nx / len, ny: ny / len, alen: Math.hypot(b.x - a.x, b.y - a.y) }
}

function drawSegmentEqualMark(ctx, a, b, style = 'tick', along = 0) {
  const { nx, ny, alen } = segPerpUnit(a, b)
  const ux = (b.x - a.x) / (alen || 1)
  const uy = (b.y - a.y) / (alen || 1)
  const t = Math.max(0.22, Math.min(0.78, 0.5 + along))
  const cx = a.x + ux * alen * t
  const cy = a.y + uy * alen * t
  const tick = 9
  ctx.strokeStyle = '#334155'
  ctx.fillStyle = '#334155'
  ctx.lineWidth = 2
  ctx.lineCap = 'round'

  const st = String(style).toLowerCase()
  if (st === 'cross' || st === 'x') {
    const d = tick * 0.55
    const ax = nx * d
    const ay = ny * d
    const bx = ux * d
    const by = uy * d
    ctx.beginPath()
    ctx.moveTo(cx - ax - bx, cy - ay - by)
    ctx.lineTo(cx + ax + bx, cy + ay + by)
    ctx.moveTo(cx - ax + bx, cy - ay + by)
    ctx.lineTo(cx + ax - bx, cy + ay - by)
    ctx.stroke()
    return
  }
  if (st === 'dbl' || st === 'double' || st === '||') {
    const off = 4
    for (const s of [-1, 1]) {
      const px = cx + ux * off * s
      const py = cy + uy * off * s
      ctx.beginPath()
      ctx.moveTo(px - (nx * tick) / 2, py - (ny * tick) / 2)
      ctx.lineTo(px + (nx * tick) / 2, py + (ny * tick) / 2)
      ctx.stroke()
    }
    return
  }
  if (st === 'dot') {
    ctx.beginPath()
    ctx.arc(cx, cy, 3.2, 0, Math.PI * 2)
    ctx.fill()
    return
  }
  ctx.beginPath()
  ctx.moveTo(cx - (nx * tick) / 2, cy - (ny * tick) / 2)
  ctx.lineTo(cx + (nx * tick) / 2, cy + (ny * tick) / 2)
  ctx.stroke()
}

function drawParallelChevrons(ctx, a, b, count = 1) {
  const alen = Math.hypot(b.x - a.x, b.y - a.y) || 1
  const ux = (b.x - a.x) / alen
  const uy = (b.y - a.y) / alen
  const px = -uy
  const py = ux
  const mx = (a.x + b.x) / 2
  const my = (a.y + b.y) / 2
  const step = 14
  const n = Math.max(1, Math.min(3, Number(count) || 1))
  ctx.strokeStyle = '#475569'
  ctx.fillStyle = '#475569'
  ctx.lineWidth = 1.75
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  for (let i = 0; i < n; i += 1) {
    const cx = mx + ux * (i - (n - 1) / 2) * step
    const cy = my + uy * (i - (n - 1) / 2) * step
    const tip = 5
    const wing = 4
    ctx.beginPath()
    ctx.moveTo(cx + ux * tip, cy + uy * tip)
    ctx.lineTo(cx - ux * wing + px * wing * 0.65, cy - uy * wing + py * wing * 0.65)
    ctx.lineTo(cx - ux * wing - px * wing * 0.65, cy - uy * wing - py * wing * 0.65)
    ctx.closePath()
    ctx.fill()
  }
}

function strokeSegment(ctx, a, b, cmd) {
  ctx.strokeStyle = cmd.stroke || cmd.color || '#0f172a'
  ctx.lineWidth = cmd.width ?? cmd.strokeWidth ?? 2.5
  ctx.lineCap = cmd.arrow || cmd.vector ? 'butt' : 'round'
  const len = Math.hypot(b.x - a.x, b.y - a.y) || 1
  const ux = (b.x - a.x) / len
  const uy = (b.y - a.y) / len
  const arrow = cmd.arrow === true || cmd.vector === true
  const head = arrow ? Math.min(14, len * 0.22) : 0
  const x2 = arrow ? b.x - ux * head : b.x
  const y2 = arrow ? b.y - uy * head : b.y
  if (cmd.dashed) ctx.setLineDash([7, 5])
  ctx.beginPath()
  ctx.moveTo(a.x, a.y)
  ctx.lineTo(x2, y2)
  ctx.stroke()
  if (cmd.dashed) ctx.setLineDash([])
  if (arrow) drawArrowHead(ctx, b.x, b.y, ux, uy, head, cmd.stroke || cmd.color || '#0f172a')
}

function drawArrowHead(ctx, tipX, tipY, ux, uy, size, color) {
  const px = -uy
  const py = ux
  const wing = size * 0.42
  ctx.fillStyle = color
  ctx.strokeStyle = color
  ctx.lineWidth = 1
  ctx.lineJoin = 'round'
  ctx.beginPath()
  ctx.moveTo(tipX, tipY)
  ctx.lineTo(tipX - ux * size + px * wing, tipY - uy * size + py * wing)
  ctx.lineTo(tipX - ux * size - px * wing, tipY - uy * size - py * wing)
  ctx.closePath()
  ctx.fill()
}

function add(a, b) {
  return { x: a.x + b.x, y: a.y + b.y }
}
function sub(a, b) {
  return { x: a.x - b.x, y: a.y - b.y }
}
function mul(v, s) {
  return { x: v.x * s, y: v.y * s }
}
function norm(v) {
  const l = Math.hypot(v.x, v.y) || 1
  return { x: v.x / l, y: v.y / l }
}

function segEdgeKey(a, b) {
  return [a, b].sort().join('\0')
}

/** Các cạnh suy ra từ spec (để chọn trên canvas). */
export function collectDrawSegments(spec) {
  const segs = []
  const seen = new Set()
  const addSeg = (from, to) => {
    if (!from || !to || from === to) return
    const k = segEdgeKey(from, to)
    if (seen.has(k)) return
    seen.add(k)
    segs.push({ from, to })
  }
  for (const c of spec?.commands || []) {
    if (!c) continue
    const op = String(c.op || '').toLowerCase()
    if (op === 'polygon') {
      const pts = c.points || c.vertices || []
      for (let i = 0; i < pts.length - 1; i += 1) addSeg(pts[i], pts[i + 1])
      if (c.closed !== false && pts.length > 2) addSeg(pts[pts.length - 1], pts[0])
      continue
    }
    if (op !== 'segment' && op !== 'segment3d' && op !== 'connect') continue
    if (c.from && c.to) addSeg(c.from, c.to)
    const chain = c.points || c.path
    if (Array.isArray(chain)) {
      for (let i = 0; i < chain.length - 1; i += 1) addSeg(chain[i], chain[i + 1])
    }
  }
  return segs
}

function distPointToSegment(px, py, ax, ay, bx, by) {
  const dx = bx - ax
  const dy = by - ay
  const len2 = dx * dx + dy * dy
  if (len2 < 1e-6) return Math.hypot(px - ax, py - ay)
  let t = ((px - ax) * dx + (py - ay) * dy) / len2
  t = Math.max(0, Math.min(1, t))
  const qx = ax + t * dx
  const qy = ay + t * dy
  return Math.hypot(px - qx, py - qy)
}

/**
 * Chọn điểm hoặc cạnh tại tọa độ canvas (sau renderDrawSpec).
 * @returns {{ type:'point', id:string } | { type:'edge', from:string, to:string } | null}
 */
export function pickDrawAt(layout, spec, canvasX, canvasY, options = {}) {
  const points = layout?.points || {}
  const pointRadius = options.pointRadius ?? 16
  const edgeRadius = options.edgeRadius ?? 18
  const preferEdge = options.preferEdge === true

  let bestPoint = null
  let bestPd = Infinity
  for (const [id, p] of Object.entries(points)) {
    const d = Math.hypot(p.x - canvasX, p.y - canvasY)
    if (d < bestPd) {
      bestPd = d
      bestPoint = id
    }
  }

  let bestEdge = null
  let bestEd = Infinity
  for (const s of collectDrawSegments(spec)) {
    const a = points[s.from]
    const b = points[s.to]
    if (!a || !b) continue
    const d = distPointToSegment(canvasX, canvasY, a.x, a.y, b.x, b.y)
    if (d < bestEd) {
      bestEd = d
      bestEdge = s
    }
  }

  const pointHit = bestPoint != null && bestPd <= pointRadius
  const edgeHit = bestEdge != null && bestEd <= edgeRadius

  if (preferEdge && edgeHit) return { type: 'edge', from: bestEdge.from, to: bestEdge.to }
  if (pointHit && edgeHit) {
    if (bestEd + 2 < bestPd) return { type: 'edge', from: bestEdge.from, to: bestEdge.to }
    if (bestPd + 2 < bestEd) return { type: 'point', id: bestPoint }
    return bestEd <= bestPd
      ? { type: 'edge', from: bestEdge.from, to: bestEdge.to }
      : { type: 'point', id: bestPoint }
  }
  if (pointHit) return { type: 'point', id: bestPoint }
  if (edgeHit) return { type: 'edge', from: bestEdge.from, to: bestEdge.to }
  return null
}

export function formatDrawSelection(sel) {
  if (!sel) return ''
  if (sel.type === 'point') return sel.id || ''
  if (sel.type === 'edge') return `${sel.from || ''}${sel.to || ''}`
  return ''
}
